/**
 * Optional but real cross-check against the platform's reference exam.
 *
 *   npm run test:reference
 *
 * Recomputes SHA-256 of grade5-math-unit1's config/submit/report files and compares
 * them with the hashes recorded in tests/fixtures/grade5-contract.json (which was
 * generated by executing those very functions). It also checks that this exam still
 * uses the reference URL/token and never reuses the reference EXAM_ID.
 * If the sibling reference folder is not checked out, the check is reported as skipped.
 */
import { createHash } from "node:crypto";
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(fileURLToPath(new URL("..", import.meta.url)));
const ref = path.resolve(root, "..", "grade5-math-unit1");
const contract = JSON.parse(readFileSync(path.join(root, "tests/fixtures/grade5-contract.json"), "utf8"));

const targets = {
  configSha256: "src/config.ts",
  submitSha256: "src/exam/submit.ts",
  reportSha256: "src/exam/report.ts",
};

if (!existsSync(path.join(ref, "src/config.ts"))) {
  console.log("SKIP: grade5-math-unit1 is not checked out next to this exam.");
  process.exit(0);
}

let failures = 0;
const check = (ok, message) => {
  console.log((ok ? "  ✓ " : "  ✗ ") + message);
  if (!ok) failures++;
};

for (const [key, rel] of Object.entries(targets)) {
  const digest = createHash("sha256").update(readFileSync(path.join(ref, rel))).digest("hex");
  check(digest === contract.provenance[key], `${rel} unchanged since the fixture was recorded`);
}

const cfg = readFileSync(path.join(root, "src/config.ts"), "utf8");
check(cfg.includes(contract.url), "SHEETS_URL is the reference deployment");
check(cfg.includes(contract.token), "SHEETS_TOKEN is the reference token");
check(cfg.includes('EXAM_ID = "grade4-english-curriculum-l1-l5"'), "EXAM_ID is this exam's folder");
check(!cfg.includes(`EXAM_ID = "${contract.referenceExamId}"`), "reference EXAM_ID was not reused");

const page = readFileSync(path.join(root, "index.html"), "utf8");
check(page.includes("Curriculum Test Lessons 1 to 5"), "official title present in <title>");
check(/grade[-_ ]?4/i.test(page) && /english/i.test(page), "grade 4 + English detectable from <title>");
check(/semester\s*1/i.test(page), "semester 1 explicitly detectable from <title>");

console.log(failures ? `\n❌ ${failures} reference check(s) failed` : "\n✅ reference contract verified");
process.exit(failures ? 1 : 0);
